UPDATE actualites SET label_fr = '⚽ Result', titre_fr = 'Full time: CSC 4 – 0 US Biskra', resume_fr = 'Big win for the Doyen against US Biskra (4-0) at the Chahid Hamlaoui Stadium, on matchday 4 of the Ligue 1 Mobilis.', contenu_fr = 'CS Constantine beat US Biskra 4-0 on Wednesday 7 October 2026 at the Chahid Hamlaoui Stadium, on matchday 4 of the Ligue 1 Mobilis.\nGoals: Evra (37''), own goal (51''), Rebiai (55''), Djaouchi (72'').\nWith this win, the Doyen moves up to 2nd place in the standings with 7 points.'
