UPDATE actualites SET label_fr = '📅 Fixtures', titre_fr = 'CSC matches in October', resume_fr = 'The Doyen''s October fixtures: US Biskra, USM Khenchela, JS El Biar and Olympique Akbou.', contenu_fr = 'Here are CS Constantine''s Ligue 1 Mobilis fixtures for October:\n• Wednesday 7 October, 6:00 pm: CSC – US Biskra (Chahid Hamlaoui Stadium) — 4-0 win\n• Monday 12 October, 3:00 pm: USM Khenchela – CSC (Amar Hamam Stadium, Khenchela)\n• Saturday 17 October, 5:00 pm: CSC – JS El Biar (Chahid Hamlaoui Stadium)\n• Friday 23 October, 3:15 pm: Olympique Akbou – CSC (Chouhada Stadium, Akbou)'
  WHERE id = 18 AND titre_fr = 'Les matchs du CSC en octobre';
UPDATE actualites SET label_fr = '💚 Supporters', titre_fr = 'Ultras Green Army at the first training session back', resume_fr = 'The “Ultras Green Army” supporters'' group came to the first training session back to support the players and lift their spirits.', contenu_fr = 'The first training session back was marked by the presence of the “Ultras Green Army” supporters'' group, who came to support the players and lift their spirits. The fans urged them to work even harder and with commitment, to keep honouring the club''s colours and meet the supporters'' expectations.\nTheir presence had a positive effect on the players, who appreciated the gesture and said they were determined to work harder and give their best to get good results in the coming matches.\nThe group created a great atmosphere during the session, with songs in honour of the club. These scenes show their attachment and loyalty to the Doyen, and confirm once again that the bond between the team and its fans rests on constant support, whatever happens.\nLong live the Doyen in the hearts of its supporters!'
  WHERE id = 19 AND titre_fr = 'Les Ultras Green Army présents à la reprise';
UPDATE actualites SET label_fr = '🏃 Training', titre_fr = 'Back to training after a day off', resume_fr = 'After a day off, the team returned to training with an evening session.', contenu_fr = 'After a day off, the CS Constantine players returned to training with an evening session led by the coaching staff.\nThe squad continues its preparation for the trip to Khenchela on Monday 12 October 2026 at 3:00 pm, on matchday 5 of the Ligue 1 Mobilis.'
  WHERE id = 20 AND titre_fr = 'Retour à l''entraînement après un jour de repos';
UPDATE actualites SET label_fr = '📢 Statement', titre_fr = 'Official statement: Marouani Amara head coach, Dr Kacemi Abdelmalek sporting technical director', resume_fr = 'The CSC board appoints Mr Marouani Amara as first-team head coach and Prof. Dr Kacemi Abdelmalek as the club''s sporting technical director.', contenu_fr = 'As part of the CS Constantine board''s efforts to strengthen its technical and organisational structures and give the first-team staff the skills it needs, and following the meeting of the committee in charge of reviewing the candidates'' applications, the following has been decided:\n• Mr Marouani Amara is appointed head coach of the first team (seniors), together with his coaching staff.\n• Prof. Dr Kacemi Abdelmalek is appointed sporting technical director of the club.\nThese appointments are part of the board''s vision of a more effective technical and administrative organisation and better coordination between all parts of the club, to ensure good working conditions, reach the sporting objectives and improve performances and results, in line with the club''s ambitions and the expectations of its loyal supporters.\nThe board congratulates both men on this vote of confidence and wishes them every success in their new roles. It stresses the importance of working together, with a sense of responsibility and team spirit, in the service of the club''s colours and to defend its history and standing.\nThe board also reaffirms its commitment to keep working to give the team the best possible conditions, so that it meets the expectations of its supporters, who have always been and will remain the true strength of CS Constantine.\nEvery success to our club, with more brilliance and more victories to come.\n“Together for CS Constantine” — The CS Constantine board'
  WHERE id = 21 AND titre_fr = 'Communiqué officiel : Marouani Amara entraîneur, Dr Kacemi Abdelmalek directeur technique sportif';
UPDATE actualites SET label_fr = '📋 Line-up', titre_fr = 'Starting XI: JS Saoura – CSC', resume_fr = 'The Doyen''s starting XI against JS Saoura.', contenu_fr = 'CS Constantine''s starting XI against JS Saoura:\nMelala (GK) – Meddahi (C), Chikhi, Zeghad, Atibu, Bizimana, Berkane, Bakir, Lahmeri, L''Ghoul, Evra.\nSubstitutes: Necir, Benmoussa, Belgourai, Ayoune, Rogers, Chaban, Djaouchi, Chekal, Ykhlef.'
  WHERE id = 22 AND titre_fr = 'Starting XI : JS Saoura – CSC';
